query PrActivityQuery($owner: String!, $name: String!, $number: Int!) {
  repository(owner: $owner, name: $name) {
    pullRequest(number: $number) {
      id
      comments(last: 100) {
        totalCount
        nodes {
          fullDatabaseId
          author {
            login
          }
          body
          createdAt
        }
      }
      reviews(last: 50) {
        totalCount
        nodes {
          author {
            login
          }
          state
          body
          submittedAt
        }
      }
      commits(last: 100) {
        totalCount
        nodes {
          commit {
            oid
            message
            committedDate
            author {
              name
              user {
                login
              }
            }
          }
        }
      }
    }
  }
}
